import{_ as d,o,c as e,a4 as r}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"临时 root (Temproot) 能力边界分析","description":"","frontmatter":{"title":"临时 root (Temproot) 能力边界分析","date":"2026-08-12T00:00:00.000Z"},"headers":[],"relativePath":"posts/临时root_能力边界_总结.md","filePath":"posts/临时root_能力边界_总结.md"}'),a={name:"posts/临时root_能力边界_总结.md"};function i(l,t,n,c,h,s){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="临时-root-temproot-能力边界分析" tabindex="-1">临时 root (Temproot) 能力边界分析 <a class="header-anchor" href="#临时-root-temproot-能力边界分析" aria-label="Permalink to &quot;临时 root (Temproot) 能力边界分析&quot;">​</a></h1><h2 id="什么是临时-root" tabindex="-1">什么是临时 root <a class="header-anchor" href="#什么是临时-root" aria-label="Permalink to &quot;什么是临时 root&quot;">​</a></h2><p>临时 root 指通过内核漏洞（如 CVE-2019-2215）在不解锁 bootloader、不刷机、不修改系统分区的情况下，<strong>在当前运行会话中</strong>获得 root 权限。重启后恢复原状，不留持久痕迹。</p><h2 id="已获得的能力" tabindex="-1">已获得的能力 <a class="header-anchor" href="#已获得的能力" aria-label="Permalink to &quot;已获得的能力&quot;">​</a></h2><h3 id="_1-dac-层面-linux-传统权限-✅-完全控制" tabindex="-1">1. DAC 层面（Linux 传统权限）✅ 完全控制 <a class="header-anchor" href="#_1-dac-层面-linux-传统权限-✅-完全控制" aria-label="Permalink to &quot;1. DAC 层面（Linux 传统权限）✅ 完全控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>uid=0 (root)</td><td>所有进程的 root 用户身份</td></tr><tr><td>gid=0</td><td>root 组</td></tr><tr><td>全部 38 种 capabilities</td><td><code>CAP_DAC_OVERRIDE</code>, <code>CAP_SYS_ADMIN</code>, <code>CAP_NET_ADMIN</code> 等全部设置</td></tr><tr><td>任意进程操控</td><td>可通过 <code>ptrace</code> 附加任何进程（需 SELinux 允许）</td></tr><tr><td>系统调用</td><td>所有系统调用均可执行（seccomp 已禁用）</td></tr></tbody></table><h3 id="_2-内核层面-kernel-r-w-✅-部分控制" tabindex="-1">2. 内核层面（Kernel R/W）✅ 部分控制 <a class="header-anchor" href="#_2-内核层面-kernel-r-w-✅-部分控制" aria-label="Permalink to &quot;2. 内核层面（Kernel R/W）✅ 部分控制&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>任意内核内存读</td><td>通过 <code>addr_limit</code> 覆盖 + pipe 技巧，可读任意内核地址</td></tr><tr><td>任意内核内存写</td><td>同原理，可写任意内核地址（但受 hypervisor 保护的区域除外）</td></tr><tr><td>修改进程 cred</td><td>已实现：uid=0, gid=0, 所有 capabilities</td></tr><tr><td>禁用 seccomp</td><td>已实现</td></tr><tr><td>读 kallsyms 符号表</td><td>已实现（通过地址表直接读取）</td></tr><tr><td>修改页表</td><td>理论上可行，但复杂高风险</td></tr></tbody></table><h3 id="_3-用户态权限-✅-有限" tabindex="-1">3. 用户态权限 ✅ 有限 <a class="header-anchor" href="#_3-用户态权限-✅-有限" aria-label="Permalink to &quot;3. 用户态权限 ✅ 有限&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>能/不能</th><th>说明</th></tr></thead><tbody><tr><td>读 <code>/proc/</code></td><td>✅</td><td>大部分可读</td></tr><tr><td>读 <code>/sys/</code></td><td>✅</td><td>大部分可读</td></tr><tr><td>写 <code>/proc/sys/</code></td><td>❌</td><td>SELinux 阻止</td></tr><tr><td>写 <code>/sys/fs/selinux/</code></td><td>❌</td><td>SELinux 阻止</td></tr><tr><td>读 <code>/data/data/</code></td><td>❌</td><td>SELinux 阻止</td></tr><tr><td>读 <code>/data/local/tmp/</code></td><td>❌</td><td>华为策略锁死</td></tr><tr><td>执行 <code>su</code></td><td>❌</td><td>无 su 二进制</td></tr><tr><td>执行 <code>chroot</code></td><td>⚠️ 可运行但无效</td><td>见下文</td></tr><tr><td>执行 <code>mount</code></td><td>⚠️ 部分受限</td><td>SELinux 阻止重新挂载</td></tr><tr><td>加载内核模块</td><td>❌</td><td>SELinux 阻止</td></tr><tr><td>持久化 root</td><td>❌</td><td>重启后恢复</td></tr></tbody></table><h2 id="为什么-uid-0-所有-caps-还不够" tabindex="-1">为什么 uid=0 + 所有 caps 还不够？ <a class="header-anchor" href="#为什么-uid-0-所有-caps-还不够" aria-label="Permalink to &quot;为什么 uid=0 + 所有 caps 还不够？&quot;">​</a></h2><p><strong>SELinux 是 Mandatory Access Control (MAC)，与 DAC 是正交的。</strong></p><ul><li>DAC（Linux 传统权限）：基于 uid/gid，root 不受限</li><li>MAC（SELinux）：基于安全上下文，<strong>root 也受限制</strong></li></ul><p>即使 uid=0 + 所有 capabilities，SELinux 仍然检查每个操作的权限。华为的 SELinux 策略对 <code>shell</code> 域（<code>u:r:shell:s0</code>）的限制极严，几乎所有敏感操作都拒绝。</p><h2 id="chroot-为什么没用" tabindex="-1">Chroot 为什么没用 <a class="header-anchor" href="#chroot-为什么没用" aria-label="Permalink to &quot;Chroot 为什么没用&quot;">​</a></h2><h3 id="chroot-的原理" tabindex="-1">Chroot 的原理 <a class="header-anchor" href="#chroot-的原理" aria-label="Permalink to &quot;Chroot 的原理&quot;">​</a></h3><p><code>chroot</code> 改变当前进程的根目录（<code>/</code>），使进程无法访问新根以外的路径。</p><h3 id="为什么对绕过-selinux-无效" tabindex="-1">为什么对绕过 SELinux 无效 <a class="header-anchor" href="#为什么对绕过-selinux-无效" aria-label="Permalink to &quot;为什么对绕过 SELinux 无效&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>chroot /data/local/tmp/myroot /bin/sh</span></span></code></pre></div><ol><li><strong>SELinux 检查基于 inode，不基于路径</strong>：即使换了根目录，文件系统仍然是同一个，inode 不变，安全上下文不变</li><li><strong>权限不继承</strong>：新根里的文件依然有原来的 SELinux 标签（<code>u:object_r:app_data_file:s0</code>），<code>shell</code> 域依然没有权限</li><li><strong><code>chroot</code> 需要的 /data 访问本身就被 SELinux 阻止</strong>：连 <code>chroot</code> 的目标目录 <code>/data/local/tmp/</code> 都访问不了</li></ol><h3 id="唯一可能有用的场景" tabindex="-1">唯一可能有用的场景 <a class="header-anchor" href="#唯一可能有用的场景" aria-label="Permalink to &quot;唯一可能有用的场景&quot;">​</a></h3><p>如果目标是<strong>在一个不受 SELinux 限制的目录中运行程序</strong>（比如 <code>/dev/</code> 下的 tmpfs），<code>chroot</code> 可以创建一个隔离环境，但在这个环境中也无法访问微信数据。</p><h2 id="这个临时-root-能做什么有意义的事" tabindex="-1">这个临时 root 能做什么有意义的事 <a class="header-anchor" href="#这个临时-root-能做什么有意义的事" aria-label="Permalink to &quot;这个临时 root 能做什么有意义的事&quot;">​</a></h2><h3 id="✅-可以做的" tabindex="-1">✅ 可以做的 <a class="header-anchor" href="#✅-可以做的" aria-label="Permalink to &quot;✅ 可以做的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>读 <code>/proc/</code> 内核信息</td><td>看进程列表、内存映射、内核符号等</td></tr><tr><td>读 <code>/sys/</code> 设备信息</td><td>看硬件信息、驱动状态</td></tr><tr><td>内核调试</td><td>通过 kallsyms 读取内核符号、dump 内核内存</td></tr><tr><td>修改进程权限</td><td>改任意进程的 uid/caps（但 SELinux 限制仍存在）</td></tr><tr><td>部分硬件操作</td><td>GPIO、I2C 等（需 SELinux 允许）</td></tr><tr><td>内存取证</td><td>读取物理内存、进程内存</td></tr></tbody></table><h3 id="❌-不能做的" tabindex="-1">❌ 不能做的 <a class="header-anchor" href="#❌-不能做的" aria-label="Permalink to &quot;❌ 不能做的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>为什么</th></tr></thead><tbody><tr><td>读微信数据库</td><td>SELinux 阻止 <code>/data/data/</code> 访问</td></tr><tr><td>提取应用数据</td><td>同上</td></tr><tr><td>永久 root</td><td>重启后消失</td></tr><tr><td>解锁 bootloader</td><td>需要 fastboot 模式，不受理</td></tr><tr><td>刷写系统</td><td>需要解锁 BL</td></tr><tr><td>绕过 SELinux</td><td>6 种方法均失败</td></tr><tr><td>加载内核模块</td><td>SELinux 阻止</td></tr><tr><td>修改系统分区</td><td>只读挂载 + dm-verity</td></tr></tbody></table><h2 id="技术原理-为什么华为的-selinux-这么难绕" tabindex="-1">技术原理：为什么华为的 SELinux 这么难绕 <a class="header-anchor" href="#技术原理-为什么华为的-selinux-这么难绕" aria-label="Permalink to &quot;技术原理：为什么华为的 SELinux 这么难绕&quot;">​</a></h2><h3 id="华为-hkip-hypervisor-kernel-integrity-protection" tabindex="-1">华为 HKIP（Hypervisor Kernel Integrity Protection） <a class="header-anchor" href="#华为-hkip-hypervisor-kernel-integrity-protection" aria-label="Permalink to &quot;华为 HKIP（Hypervisor Kernel Integrity Protection）&quot;">​</a></h3><ul><li>在 EL2（超管理器）层面保护内核内存</li><li>关键 SELinux 数据结构（<code>selinux_pool</code>、<code>avc_node</code>、<code>ss_initialized</code>、<code>cred-&gt;security</code>）的页面通过<strong>第二级页表</strong>设为只读</li><li>CPU 侧的写操作无法绕过，<strong>只有 GPU DMA 写入可以绕过</strong>（太复杂，未实现）</li></ul><h3 id="宏定义硬编码" tabindex="-1">宏定义硬编码 <a class="header-anchor" href="#宏定义硬编码" aria-label="Permalink to &quot;宏定义硬编码&quot;">​</a></h3><ul><li><code>selinux_enforcing</code> 是 <code>#define selinux_enforcing 1</code>（非变量），无法通过写内存禁用</li><li>这是 <code>CONFIG_SECURITY_SELINUX_DEVELOP</code> 未设置的结果</li></ul><h3 id="重启后随机化" tabindex="-1">重启后随机化 <a class="header-anchor" href="#重启后随机化" aria-label="Permalink to &quot;重启后随机化&quot;">​</a></h3><ul><li>KASLR 每次重启改变内核基址</li><li>不能硬编码任何地址</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p><strong>临时 root 能提供 uid=0 + 所有 capabilities + 内核读写能力，但无法绕过华为设备的 SELinux 保护。</strong> 在 SELinux 为 enforcing 且 <code>shell</code> 域被锁死的情况下，无法访问 <code>/data/data/</code> 下的应用数据。</p><p><strong>Chroot 等技术无法绕过 SELinux，因为 SELinux 基于 inode 标签，不基于路径。</strong></p><hr><p><em>文档编写日期：2026-08-12</em><em>设备：Huawei WAS-AL00 (Android 8.0.0)</em><em>漏洞：CVE-2019-2215 (binder UAF)</em></p>',39)])])}const b=d(a,[["render",i]]);export{p as __pageData,b as default};
